        'alt_conversions': [
            {'factor': 10, 'direction': 'divide'},  # g/L to g/dL
        ]
    },
    'Prealbumin': {
        'unit': 'mg/dL',
        'range': (10, 60),
        'alt_conversions': [
            {'factor': 10, 'direction': 'divide'},  # mg/L to mg/dL
        ]
    },
    'CRP': {
        'unit': 'mg/L',
        'range': (0.1, 50.0),
        'alt_conversions': []
    },

    # Lipids
    'Total_Cholesterol': {
