        'alt_conversions': [
            {'factor': 38.67, 'direction': 'divide'},  # mmol/L to mg/dL
        ]
    },
    'Triglycerides': {
        'unit': 'mg/dL',
        'range': (30, 2500),
        'alt_conversions': [
            {'factor': 88.57, 'direction': 'divide'},  # mmol/L to mg/dL
        ]
    },
    'Non_HDL_Cholesterol': {
        'unit': 'mg/dL',
        'range': (30, 400),
        'alt_conversions': [
            {'factor': 38.67, 'direction': 'divide'},  # mmol/L to mg/dL
        ]
    },

    # Glucose Metabolism
    'Glucose': {
        'unit': 'mg/dL',
        'range': (40, 1000),
        'alt_conversions': [
            {'factor': 18.02, 'direction': 'divide'},  # mmol/L to mg/dL
        ]
