    Parse a value that might have:
    - Scientific notation (1.23e+02)
    - Comma as decimal separator (12,34)
    - Both issues combined

    Returns float or np.nan if parsing fails.
    """
    if pd.isna(val):
        return np.nan

    if isinstance(val, (int, float)):
        return float(val)

    val = str(val).strip()

    if val == '' or val.lower() in ['nan', 'na', 'null', 'none', '']:
        return np.nan

    # Replace comma with period for decimal separator
    # But only if it looks like a decimal comma (not thousands separator)
    # Pattern: digits, comma, digits without another comma after
    if ',' in val and '.' not in val:
        val = val.replace(',', '.')

    try:
        return float(val)
    except ValueError:
        return np.nan


def is_in_range(value, min_val, max_val):
    """Check if value is within the specified range."""
    return min_val <= value <= max_val


def harmonize_value(value, config):
    """
    Harmonize a single value based on the feature configuration.
    If the value is outside the expected range, try to convert it.
    """
    if pd.isna(value):
        return np.nan

    min_val, max_val = config['range']

    # If value is already in range, return it
    if is_in_range(value, min_val, max_val):
        return value

    # Try alternative unit conversions
    for conv in config.get('alt_conversions', []):
        factor = conv['factor']
        direction = conv['direction']

        if direction == 'divide':
            converted = value / factor
        else:  # multiply
            converted = value * factor

        if is_in_range(converted, min_val, max_val):
            return converted

    # If no conversion works, return original value
    # (might be a genuinely extreme value in CKD patients)
    return value


def main():
