    print(f"Number of features: {len(feature_columns)}")

    # Step 1: Parse all values (handle scientific notation and comma decimals)
    print("\nStep 1: Parsing values (handling scientific notation and comma decimals)...")
    for col in feature_columns:
        df[col] = df[col].apply(parse_value)

    # Step 2: Remove rows with any missing values
    print("\nStep 2: Removing rows with missing values...")
    rows_before = len(df)
    df = df.dropna()
    rows_after = len(df)
    print(f"Removed {rows_before - rows_after} rows with missing values")
    print(f"Remaining rows: {rows_after}")

    # Step 3: Apply unit harmonization
    print("\nStep 3: Applying unit harmonization...")
    for col in feature_columns:
        if col in FEATURE_CONFIG:
            config = FEATURE_CONFIG[col]
            df[col] = df[col].apply(lambda x: harmonize_value(x, config))
        else:
            print(f"Warning: No configuration found for column: {col}")

    # Step 4: Round all values to 2 decimal places
    print("\nStep 4: Rounding values to 2 decimal places...")
    for col in feature_columns:
        df[col] = df[col].round(2)

    # Step 5: Format output (ensure X.XX format with no scientific notation)
    print("\nStep 5: Formatting output...")

    # Create output dataframe with proper formatting
    output_df = df.copy()
    for col in feature_columns:
        # Format to exactly 2 decimal places without scientific notation
        output_df[col] = output_df[col].apply(lambda x: f"{x:.2f}" if pd.notna(x) else "")

    # Save to CSV
    output_path = '/root/ckd_lab_data_harmonized.csv'
    print(f"\nSaving harmonized data to {output_path}...")
    output_df.to_csv(output_path, index=False)
    print("Done!")

    # Print summary statistics for validation
    print("\n" + "="*60)
    print("VALIDATION SUMMARY")
    print("="*60)
    print(f"Output shape: {output_df.shape}")
    print(f"Columns: {len(output_df.columns)}")

