    conversion_factor = config.get('conversion_factor')
    threshold = config.get('threshold')
    direction = config.get('direction')

    # If no conversion needed, return as is
    if conversion_factor is None:
        return value

    # Apply conversion based on threshold
    if direction == 'divide_above_threshold' and value > threshold:
        return value / conversion_factor
    elif direction == 'multiply_below_threshold' and value < threshold:
        return value * conversion_factor

    return value


