    Parse a value that might have:
    - Scientific notation (1.23e+02)
    - Comma as decimal separator (12,34)
    """
    if pd.isna(val):
        return np.nan

    if isinstance(val, (int, float)):
        return float(val)

    val = str(val).strip()

    if val == '' or val.lower() in ['nan', 'na', 'null', 'none', '']:
        return np.nan

    # Replace comma with period for decimal separator
    if ',' in val and '.' not in val:
        val = val.replace(',', '.')

    try:
        return float(val)
    except ValueError:
        return np.nan


def is_in_range(value, target_range):
    """Check if value is within the target range."""
    return target_range[0] <= value <= target_range[1]


def harmonize_value(value, config):
    """
    Harmonize a single value based on the feature configuration.
    Apply conversions in order until one brings the value into range,
    or return the original if no conversion helps.
    """
    if pd.isna(value):
        return np.nan

    target_range = config['target_range']
    conversions = config.get('conversions', [])

    # If value is already in range, return it
    if is_in_range(value, target_range):
        return value

    # Try each conversion
    for threshold_type, threshold, operation, factor in conversions:
        should_convert = False
        if threshold_type == 'above' and value > threshold:
            should_convert = True
        elif threshold_type == 'below' and value < threshold:
            should_convert = True

        if should_convert:
            if operation == 'divide':
                converted = value / factor
            else:  # multiply
                converted = value * factor

            # Check if converted value is in range or at least closer
            if is_in_range(converted, target_range):
                return converted
            # If still outside range but conversion was applied, use converted value
            return converted

    # No conversion applied or worked, return original
    return value


def main():
