def parse_value(val):
    """
    Parse a value that might have:
    - Scientific notation (1.23e+02)
    - Comma as decimal separator (12,34)
    """
    if pd.isna(val):
        return np.nan

    if isinstance(val, (int, float)):
        return float(val)

    val = str(val).strip()

    if val == '' or val.lower() in ['nan', 'na', 'null', 'none', '']:
        return np.nan

    # Replace comma with period for decimal separator
    if ',' in val and '.' not in val:
        val = val.replace(',', '.')

    try:
        return float(val)
    except ValueError:
        return np.nan


def is_in_range(value, target_range):
    """Check if value is within the target range."""
    return target_range[0] <= value <= target_range[1]


def harmonize_value(value, config):
    """
    Harmonize a single value based on the feature configuration.
    Apply conversions - only one conversion is applied per value.
    """
    if pd.isna(value):
        return np.nan

    target_range = config['target_range']
    conversions = config.get('conversions', [])

    # If value is already in range, return it
    if is_in_range(value, target_range):
        return value

    # Try each conversion - apply only one
    for threshold_type, threshold, operation, factor in conversions:
        should_convert = False
        if threshold_type == 'above' and value > threshold:
            should_convert = True
        elif threshold_type == 'below' and value < threshold:
            should_convert = True

        if should_convert:
            if operation == 'divide':
                converted = value / factor
            else:  # multiply
                converted = value * factor
            return converted  # Return after first matching conversion

    # No conversion applied, return original
    return value


def main():
    # Read the data
    print("Reading input data...")
    df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')
    print(f"Original data shape: {df.shape}")

    # Store feature columns list
    feature_columns = [col for col in df.columns if col != 'patient_id']
    print(f"Number of features: {len(feature_columns)}")

    # Step 1: Parse all values (handle scientific notation and comma decimals)
    print("\nStep 1: Parsing values (handling scientific notation and comma decimals)...")
    for col in feature_columns:
        df[col] = df[col].apply(parse_value)

    # Step 2: Remove rows with any missing values
    print("\nStep 2: Removing rows with missing values...")
    rows_before = len(df)
    df = df.dropna()
    rows_after = len(df)
    print(f"Removed {rows_before - rows_after} rows with missing values")
    print(f"Remaining rows: {rows_after}")

    # Step 3: Apply unit harmonization
    print("\nStep 3: Applying unit harmonization...")
    for col in feature_columns:
        if col in FEATURE_CONFIG:
            config = FEATURE_CONFIG[col]
            df[col] = df[col].apply(lambda x, c=config: harmonize_value(x, c))
        else:
            print(f"Warning: No configuration found for column: {col}")

    # Step 4: Round all values to 2 decimal places
    print("\nStep 4: Rounding values to 2 decimal places...")
    for col in feature_columns:
        df[col] = df[col].round(2)

    # Step 5: Format output (ensure X.XX format with no scientific notation)
    print("\nStep 5: Formatting output...")

    # Create output dataframe with proper formatting
    output_df = df.copy()
    for col in feature_columns:
        # Format to exactly 2 decimal places without scientific notation
        output_df[col] = output_df[col].apply(lambda x: f"{x:.2f}" if pd.notna(x) else "")

    # Save to CSV
    output_path = '/root/ckd_lab_data_harmonized.csv'
    print(f"\nSaving harmonized data to {output_path}...")
    output_df.to_csv(output_path, index=False)
    print("Done!")

    # Print summary statistics for validation
    print("\n" + "="*60)
    print("VALIDATION SUMMARY")
    print("="*60)
    print(f"Output shape: {output_df.shape}")
    print(f"Columns: {len(output_df.columns)}")

    # Verify key features are in expected ranges
    print("\nSample value ranges after harmonization:")
    sample_features = ['Serum_Creatinine', 'Hemoglobin', 'Glucose', 'Sodium', 'eGFR',
                       'Albumin_Serum', 'Total_Protein', 'Total_Cholesterol', 'Uric_Acid',
                       'Total_Bilirubin', 'LDL_Cholesterol', 'HDL_Cholesterol', 'Triglycerides']
    for feat in sample_features:
        if feat in df.columns:
            min_val = df[feat].min()
            max_val = df[feat].max()
            median_val = df[feat].median()
            expected = FEATURE_CONFIG[feat]['target_range']
            in_range = (min_val >= expected[0] * 0.5) and (max_val <= expected[1] * 1.2)
            status = "OK" if in_range else "CHECK"
            print(f"  {feat}: min={min_val:.2f}, max={max_val:.2f}, median={median_val:.2f} [{status}]")


if __name__ == "__main__":
    main()

